CREATE TABLE IF NOT EXISTS societe (ticker TEXT PRIMARY KEY, cik TEXT, isin TEXT, nom TEXT, pays_siege TEXT, place TEXT, devise TEXT, secteur TEXT, capitalisation REAL, eligible_pea INTEGER, source_eligibilite TEXT, vaneck TEXT, vaneck_sorti_le TEXT, suivi_serveur INTEGER DEFAULT 0, maj TEXT);
CREATE INDEX IF NOT EXISTS idx_soc_univers ON societe (vaneck, eligible_pea, capitalisation);
CREATE TABLE IF NOT EXISTS comptes (ticker TEXT, exercice INTEGER, ca REAL, ebit REAL, resultat_net REAL, marge_brute REAL, cfo REAL, capex REAL, fcf REAL, actif_total REAL, tresorerie REAL, dette REAL, capitaux_propres REAL, goodwill REAL, incorporels REAL, ppe REAL, bfr_exploitation REAL, actions_diluees REAL, impot_effectif REAL, source TEXT, clot TEXT, PRIMARY KEY (ticker, exercice));
CREATE TABLE IF NOT EXISTS metriques (ticker TEXT PRIMARY KEY, roic_median REAL, roic_dernier REAL, spread_median REAL, n_ex_roic_sup_seuil INTEGER, n_ex_total INTEGER, seuil_rentabilite_forfaitaire REAL, ca_cagr REAL, fcf_cagr REAL, ebit_cagr REAL, ca_hausse_n INTEGER, ca_hausse_m INTEGER, fcf_positif_n INTEGER, fcf_positif_m INTEGER, mb_mediane REAL, mb_pente REAL, mb_residus REAL, conversion_fcf_rn REAL, actions_var_5a REAL, dette_ebitda REAL, dette_sur_ca REAL, cp_sur_ca REAL, cours REAL, plancher_epv REAL, epv_sur_cours REAL, fcf_yield REAL, per_courant REAL, per_median REAL, ecart_multiple REAL, score_moat INTEGER, biais_acquereur INTEGER DEFAULT 0, n_non_calculable INTEGER, exclusion TEXT, maj TEXT);
CREATE INDEX IF NOT EXISTS idx_screen ON metriques (score_moat, roic_median, epv_sur_cours);
CREATE INDEX IF NOT EXISTS idx_excl ON metriques (exclusion);
CREATE TABLE IF NOT EXISTS presets (nom TEXT PRIMARY KEY, filtres TEXT, tri TEXT, description TEXT, maj TEXT);
CREATE TABLE IF NOT EXISTS runs (id INTEGER PRIMARY KEY AUTOINCREMENT, debut TEXT, fin TEXT, etape TEXT, statut TEXT, lignes_ecrites INTEGER, canari TEXT, message TEXT);
